class Box
    public define content as integer;
endClass

algorithm CompareAfterCopy
    define flag as integer;
    define original as Box;
    define other as Box;
    read flag;
    original <- new Box();
    if flag = 1 then
        other <- copy(original);
    else
        other <- original;
    endIf
    if original = other then
        write 1;
    else
        write 0;
    endIf
endAlgorithm
